// Build week window: last 7 days (Mon-Sun previous week)
const today = new Date();
const d7 = new Date(today.getTime() - 7*24*60*60*1000);
const d14 = new Date(today.getTime() - 14*24*60*60*1000);

const isoDate = x => x.toISOString().split('T')[0];

// ISO week label
function getISOWeek(d) {
  const target = new Date(d.valueOf());
  const dayNr = (d.getUTCDay() + 6) % 7;
  target.setUTCDate(target.getUTCDate() - dayNr + 3);
  const firstThursday = target.valueOf();
  target.setUTCMonth(0, 1);
  if (target.getUTCDay() !== 4) target.setUTCMonth(0, 1 + ((4 - target.getUTCDay()) + 7) % 7);
  const week = 1 + Math.ceil((firstThursday - target) / 604800000);
  return d.getUTCFullYear() + '-W' + String(week).padStart(2, '0');
}

return [{ json: {
  weekLabel: getISOWeek(today),
  weekStartIso: isoDate(d7),
  prevWeekStartIso: isoDate(d14),
  todayIso: isoDate(today),
}}];

const kpis  = $('Read Daily KPIs (last 14d)').all().map(i => i.json);
const anom  = $('Read Anomalies (last 7d)').all().map(i => i.json);
const ads   = $('Read Ad Variants (last 7d)').all().map(i => i.json);
const b2b   = $('Read B2B Leads').all().map(i => i.json);
const win   = $('Prep Week Window').item.json;

const weekStart = win.weekStartIso;
const prev = win.prevWeekStartIso;

const thisWeek = kpis.filter(k => k.Date >= weekStart);
const lastWeek = kpis.filter(k => k.Date >= prev && k.Date < weekStart);

const sum = (arr, f) => arr.reduce((a,x) => a + (Number(x[f]) || 0), 0);
const avg = (arr, f) => arr.length ? sum(arr, f) / arr.length : 0;

const revThis = sum(thisWeek, 'Total Revenue');
const revLast = sum(lastWeek, 'Total Revenue');
const revChange = revLast > 0 ? ((revThis - revLast) / revLast) * 100 : 0;

const roasThis = avg(thisWeek, 'Overall ROAS');
const roasLast = avg(lastWeek, 'Overall ROAS');
const roasTrend = roasThis > roasLast * 1.05 ? 'Rising' : (roasThis < roasLast * 0.95 ? 'Declining' : 'Stable');

const adSpendThis = sum(thisWeek, 'Total Ad Spend');
const newCThis    = sum(thisWeek, 'New Customers');
const repCThis    = sum(thisWeek, 'Repeat Customers');

// Pipeline snapshot
const pipelineVal = b2b.filter(l => ['Engaged','Proposal','Negotiation'].includes(l.Stage))
  .reduce((a,l) => a + (Number(l['Estimated Monthly Value']) || 0) * 12, 0);

// Top & bottom ads
ads.sort((a,b) => (Number(b.Revenue)||0) - (Number(a.Revenue)||0));
const topAds = ads.slice(0, 5).map(a => ({ name: a['Ad Name'], rev: a.Revenue, roas: a.ROAS, cpa: a.CPA }));
const badAds = ads.filter(a => (Number(a.ROAS)||0) < 1.5 && (Number(a.Spend)||0) > 20).slice(0, 5);

// Anomalies summary
const critical = anom.filter(a => a.Severity === 'Critical').length;
const warnings = anom.filter(a => a.Severity === 'Warning').length;

// Build prompt for Claude
const prompt = `Je bent Bamboo's strategisch analist. Schrijf een wekelijks rapport in het Nederlands. Tone: nuchter, slim, niet activistisch. Spreek in "je/jij". Lead altijd met gebruikswaarde. Geen corporate taal.

DATA van deze week (${weekStart} tot vandaag):
- Omzet deze week: €${Math.round(revThis)}
- Omzet vorige week: €${Math.round(revLast)}
- Verandering: ${revChange.toFixed(1)}%
- Gemiddelde ROAS deze week: ${roasThis.toFixed(2)}
- ROAS trend: ${roasTrend}
- Ad spend deze week: €${Math.round(adSpendThis)}
- Nieuwe klanten: ${newCThis}
- Repeat klanten: ${repCThis}
- B2B pipeline jaarwaarde: €${Math.round(pipelineVal)}
- Anomalies deze week: ${critical} kritiek, ${warnings} waarschuwing

Top 5 ads:
${topAds.map(a => `- ${a.name}: €${a.rev} rev, ROAS ${a.roas}, CPA €${a.cpa}`).join('\n')}

${badAds.length ? 'Slechtste ads (ROAS<1.5):\n' + badAds.map(a => `- ${a['Ad Name']}: ROAS ${a.ROAS}, €${a.Spend} spend`).join('\n') : 'Geen slechte ads boven spend threshold.'}

OUTPUT in strict JSON:
{
  "summary": "markdown samenvatting 3-5 zinnen",
  "top_wins": "bulletlist markdown, 3-5 bullets",
  "top_concerns": "bulletlist markdown, 2-4 bullets",
  "recommendations": "genummerde lijst markdown, 3 concrete aanbevelingen",
  "action_items": "checkboxlist markdown - [ ] format, 3-6 items"
}

Belangrijk: noem Bamboo hero product (Ongebleekt 3 laags 48 rollen) als relevant. Geen morele taal. Focus op gebruikswaarde, minder verspilling, boomvrij. Output ALLEEN de JSON, geen uitleg.`;

return [{ json: { prompt, weekLabel: win.weekLabel, weekStart, revThis, revLast, revChange, roasTrend }}];

const raw = $json.content?.[0]?.text || '{}';
let parsed = {};
try {
  // Strip fences if present
  const cleaned = raw.replace(/^```(?:json)?/g,'').replace(/```$/g,'').trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = { summary: raw, top_wins: '', top_concerns: '', recommendations: '', action_items: '' };
}

const meta = $('Build Claude Prompt').item.json;

const payload = {
  'Week': meta.weekLabel,
  'Date': meta.weekStart,
  'Summary': parsed.summary || '',
  'Top Wins': parsed.top_wins || '',
  'Top Concerns': parsed.top_concerns || '',
  'Recommendations': parsed.recommendations || '',
  'Revenue This Week': meta.revThis,
  'Revenue Last Week': meta.revLast,
  'ROAS Trend': meta.roasTrend,
  'Action Items': parsed.action_items || ''
};

// Build markdown email body
const mdEmail = `# Bamboo Strategie Rapport — ${meta.weekLabel}\n\n` +
  `**Omzet deze week:** €${Math.round(meta.revThis)} (${meta.revChange > 0 ? '+' : ''}${meta.revChange.toFixed(1)}%)\n` +
  `**ROAS trend:** ${meta.roasTrend}\n\n` +
  `## Overzicht\n${parsed.summary || ''}\n\n` +
  `## Top Wins\n${parsed.top_wins || ''}\n\n` +
  `## Top Concerns\n${parsed.top_concerns || ''}\n\n` +
  `## Aanbevelingen\n${parsed.recommendations || ''}\n\n` +
  `## Actielijst\n${parsed.action_items || ''}\n`;

return [{ json: { payload, mdEmail, weekLabel: meta.weekLabel } }];
